// Command myagent is an agentic-kit consumer generated by kit-new.
//
// It wires the FULL governed stack by default:
//
//   - budget-guard with a visible USD/day cap (BudgetMaxUSDPerDay)
//   - injection detector in BLOCK mode on tool results
//   - investigation journal appended to workspace/journal.jsonl
//   - JSONL telemetry sink + cost report rendered at exit
//   - WithCost(WithTelemetry(WithRetry(base))) client composition
//   - Anthropic API key read from ANTHROPIC_API_KEY
//
// Modes:
//
//	myagent -mode mock                            # no key, no network
//	myagent -mode live                            # real API (ANTHROPIC_API_KEY)
//
// Exit codes: 0 = run completed; 1 = startup or run failure; 2 = usage error.
//
// Concurrency: single-goroutine CLI — one Run per process.
package main

import (
	"context"
	"encoding/json"
	"errors"
	"flag"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"time"

	toolregistry "github.com/geoffmilleraz/agentic-kit/foundations/agent/tool-registry"
	costtracker "github.com/geoffmilleraz/agentic-kit/foundations/cost/cost-tracker"
	budgetguard "github.com/geoffmilleraz/agentic-kit/foundations/governance/budget-guard"
	investigationjournal "github.com/geoffmilleraz/agentic-kit/foundations/investigation/investigation-journal"
	"github.com/geoffmilleraz/agentic-kit/foundations/llmclient"
	"github.com/geoffmilleraz/agentic-kit/foundations/llmclient/anthropic"
	llminstrument "github.com/geoffmilleraz/agentic-kit/foundations/llmclient/instrument"
	jsonllog "github.com/geoffmilleraz/agentic-kit/foundations/persistence/jsonl-log"
	injectiondetector "github.com/geoffmilleraz/agentic-kit/foundations/security/injection-detector"
	"github.com/geoffmilleraz/agentic-kit/foundations/telemetry/sink"
	agentharness "github.com/geoffmilleraz/agentic-kit/kits/agent-harness"
)

const (
	// apiKeyEnv names the environment variable holding the Anthropic API key.
	// The key is read once at startup and never printed, logged, or persisted.
	apiKeyEnv = "ANTHROPIC_API_KEY"

	// defaultModel is the Anthropic model used when -model is not given.
	// Also the key in the price table below.
	defaultModel = "claude-opus-4-8"

	// systemPrompt is the system-level instruction for every model call.
	// Edit this to describe your agent's purpose and constraints.
	systemPrompt = "You are a helpful assistant. Answer the user's question concisely using the available tools."

	// telemetrySource attributes the llm_call events emitted by the
	// instrument middleware. Appears in every telemetry event's Source field.
	telemetrySource = "github.com/me/myagent"

	// costLabel is the cost tracker bucket label for this program's spend.
	costLabel = "myagent"

	// BudgetMaxUSDPerDay is the hard USD/day cap enforced before every model
	// call. Raise it deliberately — not by accident. Set to 0 to disable.
	BudgetMaxUSDPerDay = 1.00

	// BudgetMaxReqPerMin is the per-minute request cap.
	BudgetMaxReqPerMin = 20

	// BudgetMaxReqPerDay is the per-day request cap.
	BudgetMaxReqPerDay = 200

	// EstimatedUSDPerCall is the per-call cost estimate fed to the budget guard
	// before each model call. This is a conservative estimate — actual cost is
	// tracked separately by the cost tracker. Tune it to your typical call.
	EstimatedUSDPerCall = 0.05
)

// priceTable prices the models this agent might use.
//
// THE NUMBERS ARE ILLUSTRATIVE (Anthropic list prices, USD per million tokens,
// mid-2026). Verify against the provider's pricing page before trusting cost
// reports. Models absent from the table still record their tokens at zero cost.
func priceTable() costtracker.PriceTable {
	return costtracker.PriceTable{
		"claude-opus-4-8":   {InputPerMTok: 5.00, OutputPerMTok: 25.00, CacheReadPerMTok: 0.50, CacheWritePerMTok: 6.25},
		"claude-sonnet-4-6": {InputPerMTok: 3.00, OutputPerMTok: 15.00, CacheReadPerMTok: 0.30, CacheWritePerMTok: 3.75},
		"claude-haiku-4-5":  {InputPerMTok: 1.00, OutputPerMTok: 5.00, CacheReadPerMTok: 0.10, CacheWritePerMTok: 1.25},
	}
}

// injectionRules is the starter set of prompt-injection detection rules.
// Add org-specific patterns here; IDs and patterns are plain data.
func injectionRules() []injectiondetector.Rule {
	return []injectiondetector.Rule{
		{
			ID:          "INJ-001",
			Pattern:     `(?i)ignore\s+(all\s+)?previous\s+instructions?`,
			Severity:    injectiondetector.SeverityHigh,
			Description: "Classic instruction-override attempt in tool output.",
		},
		{
			ID:          "INJ-002",
			Pattern:     `(?i)you\s+are\s+now\s+a`,
			Severity:    injectiondetector.SeverityMedium,
			Description: "Role-reassignment attempt in tool output.",
		},
	}
}

// mockScript returns the scripted responses for -mode mock.
// Edit or extend this to match your agent's expected tool calls.
func mockScript() []llmclient.MockEntry {
	return []llmclient.MockEntry{
		llmclient.MockEntryWithResponse(llmclient.Response{
			Text:       "Hello! I'm your governed agent. I'm ready to help.",
			StopReason: llmclient.StopEndTurn,
			Usage:      llmclient.Usage{InputTokens: 100, OutputTokens: 20},
		}),
	}
}

// newRegistry builds the tool registry. Add your tools here following this
// pattern: ToolDef (what the model sees) + Handler (what runs).
// Handler errors surface as is_error tool_results — the model reads them and
// adapts; they never end the run.
func newRegistry() *toolregistry.Registry {
	reg := toolregistry.New(toolregistry.Options{
		DefaultTimeout: 10 * time.Second,
	})

	// Starter tool: echo — replace or extend with your domain tools.
	reg.MustRegister(toolregistry.Tool{
		Def: llmclient.ToolDef{
			Name:        "echo",
			Description: "Return the input text unchanged. Useful for testing the tool pipeline.",
			InputSchema: toolregistry.ObjectSchema(
				toolregistry.Prop{Name: "text", Type: "string", Description: "Text to echo back.", Required: true},
			),
		},
		Handler: func(_ context.Context, input json.RawMessage) (string, error) {
			var in struct {
				Text *string `json:"text"`
			}
			if err := json.Unmarshal(input, &in); err != nil {
				return "", fmt.Errorf("invalid input: %w", err)
			}
			if in.Text == nil {
				return "", errors.New(`input field "text" is required`)
			}
			return *in.Text, nil
		},
	})

	return reg
}

// run is the testable entry point: flags in, exit code out, all I/O through
// the injected writers, environment through the injected getenv. Tests never
// touch the real process state.
func run(args []string, stdout, stderr io.Writer, getenv func(string) string) int {
	fs := flag.NewFlagSet("myagent", flag.ContinueOnError)
	fs.SetOutput(stderr)
	var (
		mode     = fs.String("mode", "mock", "client mode: mock or live")
		prompt   = fs.String("prompt", "Hello! What can you do?", "the user task")
		model    = fs.String("model", defaultModel, "model name (also the cost-table key)")
		maxTurns = fs.Int("max-turns", 8, "maximum model calls per run")
		jsonOut  = fs.Bool("json", false, "emit the RunResult as JSON on stdout")
		verbose  = fs.Bool("verbose", false, "stream telemetry events (JSONL) and cost report to stderr")
	)
	if err := fs.Parse(args); err != nil {
		return 2
	}

	switch *mode {
	case "mock", "live":
	default:
		fmt.Fprintf(stderr, "myagent: invalid -mode %q (want mock or live)\n", *mode)
		return 2
	}

	// ---- base client --------------------------------------------------------
	var base llmclient.LLMClient
	if *mode == "mock" {
		base = llmclient.NewMockClient(mockScript()...)
	} else {
		key := getenv(apiKeyEnv)
		if key == "" {
			fmt.Fprintf(stderr, "myagent: live mode needs an Anthropic API key: set %s and re-run\n", apiKeyEnv)
			return 1
		}
		c, err := anthropic.New(anthropic.Config{APIKey: key, DefaultModel: *model})
		if err != nil {
			fmt.Fprintf(stderr, "myagent: build client: %v\n", err)
			return 1
		}
		base = c
	}

	// ---- observability ------------------------------------------------------
	telemetryOut := io.Discard
	if *verbose {
		telemetryOut = stderr
	}
	snk := sink.NewJSONLSink(telemetryOut)
	tracker := costtracker.New()

	// ---- client composition -------------------------------------------------
	// WithCost(WithTelemetry(WithRetry(base))) — retry innermost so telemetry
	// and cost each observe one logical call, not one record per attempt.
	client := llminstrument.WithCost(
		llminstrument.WithTelemetry(
			llmclient.WithRetry(base, llmclient.RetryConfig{
				MaxAttempts: 3,
				BaseDelay:   500 * time.Millisecond,
				Jitter:      true,
			}),
			snk, telemetrySource, time.Now,
		),
		tracker, priceTable(), costLabel,
	)

	// ---- governance: budget guard -------------------------------------------
	var budget *budgetguard.Guard
	if BudgetMaxUSDPerDay > 0 {
		budget = budgetguard.New(budgetguard.Config{
			MaxReqPerMin: BudgetMaxReqPerMin,
			MaxReqPerDay: BudgetMaxReqPerDay,
			MaxUSDPerDay: BudgetMaxUSDPerDay,
		}, time.Now)
	}

	// ---- governance: injection detector ------------------------------------
	detector, err := injectiondetector.NewDetector(injectionRules())
	if err != nil {
		fmt.Fprintf(stderr, "myagent: build injection detector: %v\n", err)
		return 1
	}

	// ---- journal: workspace/journal.jsonl -----------------------------------
	if err := os.MkdirAll("workspace", 0o755); err != nil {
		fmt.Fprintf(stderr, "myagent: create workspace dir: %v\n", err)
		return 1
	}
	journalPath := filepath.Join("workspace", "journal.jsonl")
	jf, err := jsonllog.OpenFile(journalPath)
	if err != nil {
		fmt.Fprintf(stderr, "myagent: open journal: %v\n", err)
		return 1
	}
	defer jf.Close()

	journal := investigationjournal.NewJournalWithClock(time.Now)
	journal.AttachSink(investigationjournal.JSONLSink(jf.Writer))

	// ---- tools ---------------------------------------------------------------
	registry := newRegistry()

	// ---- harness -------------------------------------------------------------
	// InjectionAction defaults to BLOCK — tool results flagged by the detector
	// are withheld from the model. Change to InjectionAnnotate to see the raw
	// content with a warning trailer instead.
	h, err := agentharness.New(
		agentharness.Config{
			MaxTurns:            *maxTurns,
			System:              systemPrompt,
			Model:               *model,
			MaxTokensPerCall:    1024,
			EstimatedUSDPerCall: EstimatedUSDPerCall,
			InjectionAction:     agentharness.InjectionBlock,
		},
		agentharness.Deps{
			Client:   client,
			Registry: registry,
			Budget:   budget,
			Detector: detector,
			Sink:     snk,
			Journal:  journal,
			Now:      time.Now,
		},
	)
	if err != nil {
		fmt.Fprintf(stderr, "myagent: build harness: %v\n", err)
		return 1
	}

	result, runErr := h.Run(context.Background(), *prompt)

	// ---- render result ------------------------------------------------------
	// RunResult is always meaningful — render first, report errors after.
	if *jsonOut {
		enc := json.NewEncoder(stdout)
		enc.SetIndent("", "  ")
		if err := enc.Encode(result); err != nil {
			fmt.Fprintf(stderr, "myagent: encode result: %v\n", err)
			return 1
		}
	} else {
		fmt.Fprintf(stdout, "stop=%s turns=%d tool_calls=%d input_tokens=%d output_tokens=%d\n\n%s\n",
			result.Stop, result.Turns, result.ToolCalls,
			result.Usage.InputTokens, result.Usage.OutputTokens, result.FinalText)
	}

	// ---- cost report --------------------------------------------------------
	if *mode == "live" || *verbose {
		fmt.Fprint(stderr, tracker.Report())
	}

	if runErr != nil {
		fmt.Fprintf(stderr, "myagent: %v\n", runErr)
		return 1
	}
	if result.Stop != agentharness.StopCompleted {
		fmt.Fprintf(stderr, "myagent: run stopped without completing: %s\n", result.Stop)
		return 1
	}
	return 0
}

func main() {
	os.Exit(run(os.Args[1:], os.Stdout, os.Stderr, os.Getenv))
}
